SELECT id AS id, target_type AS targetType, target_id AS targetId, target_code AS targetCode, binding_type AS bindingType, binding_key AS bindingKey, binding_name AS bindingName, binding_config AS bindingConfig, description AS description, status AS status, sort_order AS sortOrder, create_time AS createTime, update_time AS updateTime FROM ai_business_binding WHERE tenant_id = #{tenantId}
AND target_type = #{query.targetType}
AND target_id = #{query.targetId}
AND target_code = #{query.targetCode}
AND binding_type = #{query.bindingType}
AND status = #{query.status}
ORDER BY sort_order ASC, id ASC

