mapper.select:
SELECT
  COUNT(1) AS totalCount,
  SUM(CASE WHEN status = 1 THEN 1 ELSE 0 END) AS runnableCount
FROM ai_business_binding
WHERE tenant_id = #{tenantId}
  AND binding_type = #{capabilityType}

SELECT

FROM ai_business_binding
WHERE tenant_id = #{tenantId}
  AND target_type = #{targetType}
  AND target_code = #{targetCode}
  AND binding_type = #{bindingType}
ORDER BY status DESC,
         CASE WHEN binding_key IS NULL OR binding_key = '' THEN 1 ELSE 0 END,
         CASE WHEN binding_config IS NULL OR binding_config = '' THEN 1 ELSE 0 END,
         sort_order ASC,
         update_time DESC,
         id DESC
LIMIT 1

SELECT COALESCE(NULLIF(b.binding_key, ''), #{modelKey}) AS flowModelKey,

FROM ai_business_binding b

WHERE b.tenant_id = #{tenantId}
  AND b.target_type = 'OBJECT'
  AND b.binding_type IN ('FLOW', 'APPROVAL')
  AND b.status = 1
  AND o.id IS NOT NULL
  AND (
    b.binding_key = #{modelKey}
    OR b.binding_config LIKE #{modelKeyLikeNeedle}
  )
ORDER BY COALESCE(o.sort_order, 0) ASC, b.sort_order ASC, b.id ASC

SELECT b.binding_key AS flowModelKey,
FROM ai_business_binding b
WHERE b.tenant_id = #{tenantId} AND b.target_type = 'OBJECT' AND b.binding_type IN ('FLOW', 'APPROVAL') AND b.status = 1 AND o.id IS NOT NULL AND (
b.binding_key IN
#{modelKey}
OR
b.binding_config LIKE #{needle}
1 = 0
) ORDER BY COALESCE(o.sort_order, 0) ASC, b.sort_order ASC, b.id ASC

SELECT 
FROM ai_business_binding
WHERE tenant_id = #{tenantId}
  AND target_type = 'APPLICATION'
  AND target_id = #{applicationId}
ORDER BY sort_order ASC, binding_type ASC, binding_key ASC, id ASC

mapper.update:
UPDATE ai_business_binding
SET binding_config = #{bindingConfig},
    status = #{status},
    sort_order = #{sortOrder},
    update_time = NOW()
WHERE tenant_id = #{tenantId}
  AND target_type = 'APPLICATION'
  AND target_id = #{applicationId}
  AND id = #{bindingId}
